    fn read_char(&mut self) -> R<Option<char>> {
        if self.inpos >= self.inbuf.len() {
            let _ = self.out.flush();
            let mut line = String::new();
            match self.input.read_line(&mut line) {
                Ok(0) => return Ok(None),
                Ok(_) => {}
